import { useMutation } from '@tanstack/react-query';
import axios from 'axios';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { resultify } from '~/shared/lib/utils/resultify';

const updateNotification = (id: string) => {
  return resultify(axios.get<any>(`${API_URLS.updateIndict(id)}`));
};

export const useUpdateNotificationMutation = (options?: MutationOptions<string, CBDCAxiosError, string>) => {
  const mutation = useMutation<string, CBDCAxiosError, string>({
    ...options,
    mutationFn: (id: string) => updateNotification(id),
  });

  return {
    ...mutation,
  };
};
