import { format, addDays } from 'date-fns';
import { Fragment, useEffect, useState, useMemo } from 'react';
import { useInView } from 'react-intersection-observer';
import { Link } from 'react-router-dom';
import {
  useSetHeaderRight,
  useSetHeaderTitle,
  useSetIsPullToRefreshEnabled,
} from '~/widgets/sub-layout/use-sub-layout';
import { useComBankInfo } from '~/entities/comcode/lib/use-com-bank-info';
import { useNotificationListInfiniteQuery } from '~/entities/notification/api/use-notification-list-infinite-query';
import { useUpdateNotificationMutation } from '~/entities/notification/api/use-update-notification-query';
import { NotificationListParams } from '~/entities/notification/model/types';
import { MessageType } from '~/shared/api/dtos/enums';
import { appConfig } from '~/shared/config';
import i18n from '~/shared/i18n/i18n';
import { parseToDate } from '~/shared/lib/web-view-bridge';
import { PATHS } from '~/shared/routes/paths';

export const NotificationListPage = () => {
  useSetIsPullToRefreshEnabled(true);
  useSetHeaderTitle(i18n.t('notification'));
  useSetHeaderRight(
    <Link type="button" to={PATHS.notification.setting} className="btn top-set-btn">
      <span>{i18n.t('notificationSettingButton')}</span>
    </Link>,
  );
  const { mutateAsync: updateNotification } = useUpdateNotificationMutation();
  const { shortBankName } = useComBankInfo(appConfig.BANK_CODE ?? '');
  const [ref, inView] = useInView();
  const [search, setSearch] = useState<NotificationListParams>({ search: { mssageTycd: MessageType.전체 } });
  const {
    data: list,
    fetchNextPage,
    hasNextPage,
    isLoading,
    isError,
    refetch,
    markAsRead,
  } = useNotificationListInfiniteQuery(search);
  const flattenList = list?.pages.map((page) => page.result.list).flat() || [];
  const hasNoList = isError || (!isLoading && flattenList.length === 0);

  // Group notifications by date
  const dateList = useMemo(() => {
    const dates: string[] = [];
    flattenList.forEach((item) => {
      const registDt = parseToDate(item.registDt, 'yyyy.MM.dd');
      if (!dates.includes(registDt)) {
        dates.push(registDt);
      }
      if (!item.isRead) {
        markAsRead(item.mssageManageId);
      }
    });
    return dates;
  }, [flattenList, markAsRead]);

  // mssageTycd [ 메시지 타입 (TP : 토큰 / 결제 | SE : 보안 | WN : 활동_소식 | CI : 전환입금 | CO : 예금전환) ]
  const fnFilter = (item: MessageType) => {
    setSearch((prev) => {
      const nextMessageType = item ?? '';

      if (prev.search.mssageTycd === nextMessageType) {
        return prev;
      }

      return { search: { mssageTycd: nextMessageType } };
    });
  };
  const fnDelete = async (item: string) => {
    await updateNotification(item);
    refetch();
  };

  useEffect(() => {
    if (hasNextPage && inView) fetchNextPage();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [hasNextPage, inView]);

  return (
    <div className="wrap">
      <div className="content sub">
        <div className="filter">
          <button
            type="button"
            className={`filter-btn ${!search.search.mssageTycd ? 'on' : ''}`}
            onClick={() => {
              fnFilter(MessageType.전체);
            }}
          >
            <span>{i18n.t('all')}</span>
          </button>
          <button
            type="button"
            className={`filter-btn ${search.search.mssageTycd === MessageType.토큰_결제 ? 'on' : ''}`}
            onClick={() => {
              fnFilter(MessageType.토큰_결제);
            }}
          >
            <span>{i18n.t('assetAndPayment')}</span>
          </button>
          <button
            type="button"
            className={`filter-btn ${search.search.mssageTycd === MessageType.보안 ? 'on' : ''}`}
            onClick={() => {
              fnFilter(MessageType.보안);
            }}
          >
            <span>{i18n.t('security')}</span>
          </button>
          <button
            type="button"
            className={`filter-btn ${search.search.mssageTycd === MessageType.활동_소식 ? 'on' : ''}`}
            onClick={() => {
              fnFilter(MessageType.활동_소식);
            }}
          >
            <span>{i18n.t('activityAndNews')}</span>
          </button>
        </div>
        <div className="alert-list">
          <p className="alert-info">{i18n.t('notificationStoragePeriod')}</p>
          {hasNoList ? (
            <div className="empty">
              <p>{i18n.t('noNotifications')}</p>
            </div>
          ) : (
            <ul>
              {dateList.map((item, index) => (
                <Fragment key={`Fragment_${index}`}>
                  <li key={`li_${index}`}>
                    <p className="date">
                      {item === format(new Date(), 'yyyy.MM.dd')
                        ? i18n.t('today')
                        : item === format(addDays(new Date(), -1), 'yyyy.MM.dd')
                          ? i18n.t('yesterday')
                          : item === format(addDays(new Date(), -2), 'yyyy.MM.dd')
                            ? i18n.t('twoDaysAgo')
                            : item}
                    </p>
                  </li>
                  {flattenList
                    ?.filter((value) => parseToDate(value.registDt, 'yyyy.MM.dd') === item)
                    .map((item2, index2) => (
                      <li key={`li2_${index2}`} ref={ref}>
                        <div className={`noti-box ${!item2.isRead ? 'new' : ''}`}>
                          <div className="noti-box-top">
                            <div className="noti-date">{parseToDate(item2.registDt, 'yyy.MM.dd HH:mm:ss')}</div>
                            <button
                              type="button"
                              className="btn close-btn sm"
                              onClick={() => {
                                fnDelete(item2.mssageManageId);
                              }}
                            >
                              <span>{i18n.t('deleteNotification')}</span>
                            </button>
                          </div>
                          <div className="noti-box-title">
                            <span>{item2.sj}</span>
                            <p>
                              {item2.mssageTycd === MessageType.전환입금 ? (
                                <>
                                  <span>
                                    {shortBankName} | {item2.aliasNm}
                                  </span>
                                  <div className="token-arr">전송</div>
                                  <span>{i18n.t('linkedAccount')}</span>
                                </>
                              ) : item2.mssageTycd === MessageType.예금전환 ? (
                                <>
                                  <span>{i18n.t('linkedAccount')}</span>
                                  <div className="token-arr">전송</div>
                                  <span>
                                    {shortBankName} | {item2.aliasNm}
                                  </span>
                                </>
                              ) : (
                                <span>
                                  {shortBankName} | {item2.aliasNm}
                                </span>
                              )}
                            </p>
                          </div>
                          <div className="noti-box-desc">
                            <p>{item2.sndngMssageCn}</p>
                          </div>
                        </div>
                      </li>
                    ))}
                </Fragment>
              ))}
            </ul>
          )}
        </div>
      </div>
    </div>
  );
};
